// Cross-check: the golden vectors the FIRMWARE encoders produced, decoded by
// the app. The app's other decoder tests hand-build bytes from the contract
// tables; this one pins the two implementations against each other, so a
// table/encoder disagreement fails here instead of in the field.
//
// The file is generated by the firmware host test (`cd nrf_firmware/tests &&
// make vectors`, see contract amendment R2) and may legitimately not exist
// while the firmware side is still being written — the test skips with that
// reason rather than failing.
import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:impulse_app/models/debug_telemetry.dart';

const _vectorPath = '../nrf_firmware/tests/vectors/debug_telemetry_v2.json';

List<int> _hex(String s) {
  final c = s.replaceAll(RegExp(r'\s'), '');
  return [
    for (var i = 0; i + 1 < c.length; i += 2)
      int.parse(c.substring(i, i + 2), radix: 16)
  ];
}

/// The wire values that mean "absent". The decoder maps these to Dart `null`
/// (a typed model is more useful to the UI than a magic number), while the
/// firmware vector file records the value the encoder was handed — which is
/// the same sentinel. This is the bridge between the two representations.
const _absentNumbers = <num>{0, 0xFE, 0xFF, 0x7FFF, 0xFFFF, 0xFFFFFFFF};

bool _isAbsentString(String s) {
  final t = s.replaceAll('-', '').replaceAll(':', '').toLowerCase();
  return t.isEmpty ||
      t == 'none' ||
      t == '0000' ||
      RegExp(r'^(0+|f+)$').hasMatch(t);
}

/// Compare one expected value against the decoder's. Booleans and 0/1 are
/// treated as the same fact, because a vector file may describe a flag either
/// way; strings are compared case-insensitively (UUIDs are lowercase, BLE
/// addresses upper-case, and neither distinction is load-bearing).
void _expectEqual(Object? actual, Object? expected, String path) {
  if (expected == null) {
    expect(actual, isNull, reason: '$path: expected null');
    return;
  }
  if (actual == null) {
    // The decoder maps the documented sentinel to null; the vector file keeps
    // the sentinel the encoder was given.
    if (expected is num) {
      expect(_absentNumbers, contains(expected),
          reason: '$path: decoder says absent, vector says $expected');
      return;
    }
    if (expected is String && _isAbsentString(expected)) return;
    if (expected is String && expected == '0.0.0.0') return;
    fail('$path: decoder says absent, vector says $expected');
  }
  if (expected is bool) {
    final value = actual is bool ? actual : (actual is num ? actual != 0 : null);
    expect(value, expected, reason: '$path: $actual vs $expected');
    return;
  }
  if (expected is num) {
    if (actual is bool) {
      expect(actual, expected != 0, reason: '$path: $actual vs $expected');
      return;
    }
    expect(actual, isA<num>(), reason: '$path: expected a number');
    expect((actual as num).toInt(), expected.toInt(),
        reason: '$path: $actual vs $expected');
    return;
  }
  if (expected is String) {
    expect(actual.toString().toLowerCase(), expected.toLowerCase(),
        reason: '$path: $actual vs $expected');
    return;
  }
  expect(actual, expected, reason: path);
}

/// Compare a flat expectation (a map of §4 names to values) with the decoded
/// map. One level of nesting is tolerated — a vector file may group the flag
/// bits under `flags0: {worn: true, ...}`; those leaves are looked up in the
/// flat map, which exposes them under their §4 names too.
///
/// Returns how many leaves were actually compared. A caller asserts a floor so
/// a schema the app does not recognise fails loudly instead of passing
/// vacuously.
int _compareFields(
    Map<String, Object?> actual, Map<String, dynamic> expected, String where) {
  var compared = 0;
  final missing = <String>[];

  void walk(Object? exp, String path) {
    if (exp is Map) {
      for (final e in exp.entries) {
        walk(e.value, e.key as String);
      }
      return;
    }
    final leaf = path.contains('.') ? path.split('.').last : path;
    if (!actual.containsKey(leaf)) {
      missing.add(path);
      return;
    }
    _expectEqual(actual[leaf], exp, '$where.$path');
    compared++;
  }

  for (final e in expected.entries) {
    walk(e.value, e.key);
  }

  expect(missing, isEmpty,
      reason: '$where: the decoder does not expose these §4 names from the '
          'vector file: $missing');
  return compared;
}

void main() {
  final file = File(_vectorPath);
  final present = file.existsSync();
  const skipReason =
      'firmware golden vectors not produced yet: expected $_vectorPath '
      '(generated by `make vectors` in nrf_firmware/tests, contract R2). '
      'The app decoder is covered independently by debug_telemetry_test.dart.';

  test('every firmware v2 golden vector decodes identically', () {
    final root = jsonDecode(file.readAsStringSync()) as Map<String, dynamic>;
    expect(root['version'], 2);
    final vectors = (root['vectors'] as List).cast<Map<String, dynamic>>();
    expect(vectors, isNotEmpty);
    expect(
      vectors.map((v) => v['name']).toList(),
      containsAll(<String>[
        'watch_sunrise_near',
        'watch_abstain_escalating',
        'anchor_beeping_ble',
      ]),
      reason: 'R2 names three required situations',
    );

    for (final vector in vectors) {
      final name = vector['name'] as String;
      final role = vector['role'] as String;
      final bytes = _hex(vector['hex'] as String);
      final fields = (vector['fields'] as Map).cast<String, dynamic>();
      final records =
          ((vector['records'] as List?) ?? const []).cast<Map<String, dynamic>>();

      switch (role) {
        case 'watch':
          final t = WatchDebugTelemetry.decode(bytes);
          final compared = _compareFields(t.fieldsMap(), fields, name);
          expect(compared, greaterThanOrEqualTo(10),
              reason: '$name: too few header fields were comparable');
          expect(t.anchors, hasLength(records.length),
              reason: '$name: record count');
          for (int i = 0; i < records.length; i++) {
            final n = _compareFields(
                t.anchors[i].toRecordMap(), records[i], '$name.records[$i]');
            expect(n, greaterThanOrEqualTo(6),
                reason: '$name.records[$i]: too few record fields compared');
          }
          break;
        case 'anchor':
          final t = AnchorDebugTelemetry.decode(bytes);
          final compared = _compareFields(t.fieldsMap(), fields, name);
          expect(compared, greaterThanOrEqualTo(10),
              reason: '$name: too few header fields were comparable');
          expect(t.events, hasLength(records.length),
              reason: '$name: record count');
          for (int i = 0; i < records.length; i++) {
            final n = _compareFields(
                t.events[i].toRecordMap(), records[i], '$name.records[$i]');
            expect(n, greaterThanOrEqualTo(4),
                reason: '$name.records[$i]: too few record fields compared');
          }
          break;
        default:
          fail('$name: unknown role "$role" (expected watch or anchor)');
      }
    }
  }, skip: present ? false : skipReason);
}
